rows=[]
with open(f) as h:
 for r in csv.DictReader(x for x in h if not x.startswith('#')): rows.append({k:float(v) for k,v in r.items()})
def cross(col, threshold):
 for a,b in zip(rows,rows[1:]):
  if a[col] < threshold <= b[col]:
   return a['time_min']+(threshold-a[col])/(b[col]-a[col])*(b['time_min']-a['time_min'])
for col,thr in [('T_unexposed_max_C',202),('T_unexposed_avg_C',160)]: print(col,thr,cross(col,thr))
# mean at governance max crossing, and differences
for t in [118,120,225]:
 x=next(r for r in rows if r['time_min']==t) if any(r['time_min']==t for r in rows) else None
 print(t,x)
print('n',len(rows), 'last',rows[-1])
